def find_permutation(n, p):
    visited = [False] * n
    q = [-1] * n

    for i in range(n):
        if not visited[i]:
            cycle = []
            x = i
            while not visited[x]:
                visited[x] = True
                cycle.append(x)
                x = p[x] - 1

            if len(cycle) % 2 == 1:
                return [-1]

            mid = len(cycle) // 2
            for j in range(mid):
                q[cycle[j]] = cycle[(j + mid) % len(cycle)] + 1
                q[cycle[(j + mid) % len(cycle)]] = cycle[j] + 1

    return q

